import { createAgentStep, createWorkflow } from "@kimchi-dev/kimchi-workflows"

const bg = createAgentStep({ name: "bg-step", model: "kimchi-dev/fake-b", background: true, prompt: () => "WF_BG_STEP SLEEP=3" })
const inSession = createAgentStep({ name: "in-session-step", model: "kimchi-dev/fake-b", prompt: () => "WF_INSESSION_STEP" })
const after = createAgentStep({ name: "after-step", prompt: () => "WF_AFTER_STEP" })

export default createWorkflow({ name: "probe", description: "delegate probe" }).then(bg).then(inSession).then(after).commit()
